			RBXASSERT(formFactor == SYMETRIC);

		if (getPartType() != _type)
		{
			destroyJoints();

			setPartTypeXml(_type);

			if (_type != Part::BLOCK_PART)
			{
				G3D::Vector3 xmlSize = uiToXmlSize(getPartSizeUi());
				setPartSizeXml(xmlSize);
				safeMove();
			}

			safeMove();
			join();
		}
