                                   _numTextureUnits,
                                   GLCaps::G3D_MAX_TEXTURE_UNITS);

        glGetIntegerv(GL_MAX_TEXTURE_IMAGE_UNITS_NV, &_numTextures);
        _numTextures = iClamp(_numTextures,
                              _numTextureUnits, 
                              GLCaps::G3D_MAX_TEXTURE_UNITS);
