    beginEndFrame = 0;
    if (debugLog) {debugLog->section("Initialization");}

    debugAssert((settings.lightSaturation >= 0.5) && 
                (settings.lightSaturation <= 2.0));

    // Under Windows, reset the last error so that our debug box
    // gives the correct results
    #ifdef G3D_WIN32
        SetLastError(0);
    #endif

