void System::memcpy(void* dst, const void* src, size_t numBytes) {
    if (System::hasSSE2() && System::hasMMX()) {
        G3D::memcpyMMX(dst, src, numBytes);
    } else if (System::hasSSE() && System::hasMMX()) {
        G3D::memcpyMMX(dst, src, numBytes);
    } else {
        ::memcpy(dst, src, numBytes);
    }
}


